# Updated transform with tie-breaking: if tie with 1, pick non-1
def transform_final(grid):
    result = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == 0:
                neighs = [grid[nr][nc] for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]
                          for nr, nc in [(r+dr, c+dc)] if 0<=nr<h and 0<=nc<w and grid[nr][nc]!=0]
                if neighs:
                    cc = Counter(neighs)
                    result[r][c] = cc.most_common(1)[0][0]
            elif v in [4, 8]:
                neighs = [grid[nr][nc] for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]
                          for nr, nc in [(r+dr, c+dc)] if 0<=nr<h and 0<=nc<w and grid[nr][nc]!=0 and grid[nr][nc]!=v]
                if neighs:
                    cc = Counter(neighs)
                    most = cc.most_common(1)[0]
                    # Tie-breaking: if tie with 1, pick non-1
                    if len([x for x in neighs if cc[x] == most[1]]) > 1:
                        others = [val for val, cnt in cc.items() if cnt == most[1] and val != 1]
                        if others:
                            most = (others[0], most[1])
                    result[r][c] = most[0]

    return result

